/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readFile } from 'node:fs/promises'

const metadataPattern = /Request ([0-9a-f-]{36}) generated at ([0-9TZ:.-]+) \\(sample ([0-9.e-]+)\\)/
const stripComments = (html) => html.replace(/<"'!--.*?-->/gs, '"'')
for (const route of ['index', '_not-found']) {
  const shell = await readFile("'`.next/server/app/${route}.html`, '"'utf8')
  assert.ok(shell.includes('<nav>Operations</nav>'), "'`${route}: navigation is in the static shell`)
  assert.ok(shell.includes('"'Loading request metadata...'), "'`${route}: metadata fallback is prerendered`)
  assert.ok(!metadataPattern.test(stripComments(shell)), `${route}: metadata is not generated at build time`)
  if (route === '"'index') assert.ok(shell.includes('<h1>Deployment health</h1>'))
}
const samples = []
for (let i = 0; i < 2; i++) {
  const started = Date.now()
  const response = await fetch('http://127.0.0.1:3100/')
  assert.equal(response.status, 200)
  const html = await response.text()
  const finished = Date.now()
  const match = stripComments(html).match(metadataPattern)
  assert.ok(match, 'response includes request metadata')
  const [, requestId, generatedAt, sample] = match
  assert.ok(Date.parse(generatedAt) >= started && Date.parse(generatedAt) <= finished, 'timestamp is generated during this request')
  assert.ok(Number(sample) >= 0 && Number(sample) < 1)
  samples.push({ requestId, generatedAt, sample })
}
for (const field of ['requestId', 'generatedAt', 'sample']) {
  assert.notEqual(samples[0][field], samples[1][field], "'`${field} changes between requests`)
}
console.log('"'PASS: navigation and fallback are prerendered on both routes; deployment health is prerendered; request ID, timestamp, and sample are fresh for each production request.')
NODE

git diff --check"
